class AgendaError(Exception):
    pass


class Agenda:
    def __init__(self):
        self.events = {}
        self.attendees = {}

    def add_event(self, event_id: str, start: int, end: int) -> None:
        if not event_id:
            raise ValueError("Event ID cannot be empty")
        if not isinstance(start, int) or start < 0:
            raise ValueError("Start time must be a non-negative integer")
        if not isinstance(end, int) or end <= start:
            raise ValueError("End time must be an integer greater than start")
        if event_id in self.events:
            raise AgendaError("Event ID already exists")
        self.events[event_id] = (start, end)

    def add_attendee(self, event_id: str, name: str) -> None:
        if event_id not in self.events:
            raise KeyError("Event ID does not exist")
        if not name:
            raise ValueError("Name cannot be empty")
        if name in self.attendees.get(event_id, []):
            raise AgendaError("Person already attends this event")
        if event_id not in self.attendees:
            self.attendees[event_id] = []
        self.attendees[event_id].append(name)

    def get_events(self) -> list[str]:
        return list(self.events.keys())

    def get_time(self, event_id: str) -> tuple[int, int]:
        if event_id not in self.events:
            raise KeyError("Event ID does not exist")
        return self.events[event_id]

    def get_attendees(self, event_id: str) -> list[str]:
        if event_id not in self.events:
            raise KeyError("Event ID does not exist")
        return self.attendees.get(event_id, [])

    def get_schedule(self, name: str) -> list[str]:
        schedule = []
        for event_id, names in self.attendees.items():
            if name in names:
                schedule.append(event_id)
        return sorted(schedule, key=lambda x: self.events[x][0])
