class ScoreError(Exception):
    pass


class ScoreBoard:
    def __init__(self):
        self.players = {}
        self.all_scores = []

    def add_player(self, name: str) -> None:
        if not name:
            raise ValueError("Empty name is not allowed")
        if name in self.players:
            raise ScoreError(f"Player '{name}' already exists")
        self.players[name] = []

    def record_score(self, name: str, score: int) -> None:
        if not isinstance(name, str):
            raise KeyError("Invalid player name")
        if not isinstance(score, int) or score < 0:
            raise ValueError("Score must be a non-negative integer")
        self.players[name].append(score)
        self.all_scores.append(score)

    def get_players(self) -> list[str]:
        return list(self.players.keys())

    def get_scores(self, name: str) -> list[int]:
        if not isinstance(name, str):
            raise KeyError("Invalid player name")
        if name not in self.players:
            raise KeyError(f"Player '{name}' not found")
        return self.players[name]

    def get_latest_score(self, name: str) -> int:
        if not isinstance(name, str):
            raise KeyError("Invalid player name")
        if name not in self.players or not self.players[name]:
            raise ScoreError(f"Player '{name}' has no scores")
        return self.players[name][-1]

    def get_total_score(self, name: str) -> int:
        if not isinstance(name, str):
            raise KeyError("Invalid player name")
        if name not in self.players:
            raise KeyError(f"Player '{name}' not found")
        return sum(self.players[name])

    def get_top_scores(self, n: int) -> list[int]:
        if not isinstance(n, int) or n < 1:
            raise ValueError("n must be a positive integer")
        return sorted(self.all_scores, reverse=True)[:n]
