        if stream_id in self.streams:
            raise MeterError(f"Stream '{stream_id}' is already open")
        self.streams[stream_id] = {
            'bytes_read': 0,
            'bytes_written': 0,
            'reads': 0,
            'writes': 0
        }
        self.stream_order.append(stream_id)

    def record_read(self, stream_id: str, size: int) -> None:
        self._check_stream(stream_id)
        if not isinstance(size, int) or size < 0:
            raise ValueError("Size must be a non-negative integer")
        self.streams[stream_id]['bytes_read'] += size
        self.streams[stream_id]['reads'] += 1

    def record_write(self, stream_id: str, size: int) -> None:
        self._check_stream(stream_id)
        if not isinstance(size, int) or size < 0:
            raise ValueError("Size must be a non-negative integer")
        self.streams[stream_id]['bytes_written'] += size
        self.streams[stream_id]['writes'] += 1

    def get_bytes_read(self, stream_id: str) -> int:
        self._check_stream(stream_id)
        return self.streams[stream_id]['bytes_read']

    def get_bytes_written(self, stream_id: str) -> int:
        self._check_stream(stream_id)
        return self.streams[stream_id]['bytes_written']

    def get_op_counts(self, stream_id: str) -> tuple[int, int]:
        self._check_stream(stream_id)
        return self.streams[stream_id]['reads'], self.streams[stream_id]['writes']

    def get_streams(self) -> list[str]:
        return self.stream_order

    def _check_stream(self, stream_id: str) -> None:
        if not isinstance(stream_id, str) or stream_id not in self.streams:
            raise KeyError(f"Stream '{stream_id}' is not open")
