            raise ValueError("Quantity must be a positive integer")
        if name not in self.items:
            raise KeyError(f"Item '{name}' not found")

        batches = self.items[name]
        used = 0

        while used < quantity and batches:
            use_by, q = batches[0]
            if q <= quantity - used:
                used += q
                batches.pop(0)
            else:
                batches[0] = (use_by, q - (quantity - used))
                used = quantity

    def get_quantity(self, name):
        if name not in self.items:
            raise KeyError(f"Item '{name}' not found")
        return sum(q for _, q in self.items[name])

    def get_batches(self, name):
        if name not in self.items:
            raise KeyError(f"Item '{name}' not found")
