class Party:
    def __init__(self):
        self.characters = {}
        self.items = {}
        self.item_definitions = {}

    def add_character(self, name: str, strength: int) -> None:
        if not isinstance(name, str) or not name:
            raise ValueError("Name must be a non-empty string")
        if not isinstance(strength, int) or strength <= 0:
            raise ValueError("Strength must be a positive integer")
        if name in self.characters:
            raise PartyError("Character already exists")
        self.characters[name] = {'bag': [], 'equipped': []}

    def define_item(self, item: str, weight: int) -> None:
        if not isinstance(item, str) or not item:
            raise ValueError("Item must be a non-empty string")
        if not isinstance(weight, int) or weight <= 0:
            raise ValueError("Weight must be a positive integer")
        if item in self.item_definitions:
            raise PartyError("Item already defined")
        self.item_definitions[item] = weight

    def give_item(self, name: str, item: str) -> None:
        if name not in self.characters:
            raise KeyError("Unknown character")
        if item not in self.item_definitions:
            raise KeyError("Unknown item")
        if item in self.characters[name]['bag']:
            raise PartyError("Character already holds this item")
        self.characters[name]['bag'].append(item)

    def equip(self, name: str, item: str) -> None:
        if name not in self.characters:
            raise KeyError("Unknown character")
        if item not in self.item_definitions:
            raise KeyError("Unknown item")
        if item not in self.characters[name]['bag']:
            raise PartyError("Character does not hold this item")
        if item in self.characters[name]['equipped']:
            raise PartyError("Character already equipped this item")
        self.characters[name]['equipped'].append(item)

    def unequip(self, name: str, item: str) -> None:
        if name not in self.characters:
            raise KeyError("Unknown character")
        if item not in self.item_definitions:
            raise KeyError("Unknown item")
        if item not in self.characters[name]['equipped']:
            raise PartyError("Character does not have this item equipped")
        self.characters[name]['equipped'].remove(item)

    def get_bag(self, name: str) -> list[str]:
        if name not in self.characters:
            raise KeyError("Unknown character")
        return self.characters[name]['bag']

    def get_equipped(self, name: str) -> list[str]:
        if name not in self.characters:
            raise KeyError("Unknown character")
        return self.characters[name]['equipped']
