        if ticket_id not in self.tickets or agent_id not in self.agents:
            raise KeyError(f"Unknown ticket or agent: {ticket_id}, {agent_id}")
        if self.tickets[ticket_id]['agent'] is not None:
            raise DeskError(f"Ticket {ticket_id} already has an agent")
        self.tickets[ticket_id]['agent'] = agent_id
        self.agents[agent_id].append(ticket_id)

