class LimiterError(Exception):
    pass


class RateLimited(LimiterError):
    pass


class RateLimiter:
    def __init__(self, window: int):
        if not isinstance(window, int) or window <= 0:
            raise ValueError("Window must be an int greater than 0")
        self.window = window
        self.time = 0
        self.clients = {}
        self.receipt_counter = 0

    def add_client(self, client_id: str, allowance: int) -> None:
        if not client_id:
            raise ValueError("Client id cannot be empty")
        if not isinstance(allowance, int) or allowance <= 0:
            raise ValueError("Allowance must be an int greater than 0")
        if client_id in self.clients:
            raise LimiterError("Client already registered")
        self.clients[client_id] = {
            'allowance': allowance,
            'current_window': 0,
            'requests': 0
        }

    def tick(self, steps: int = 1) -> None:
        if not isinstance(steps, int) or steps <= 0:
            raise ValueError("Steps must be an int greater than 0")
        self.time += steps
        for client_id, client_data in self.clients.items():
            current_window = self.time // self.window
            if client_data['current_window'] < current_window:
                client_data['current_window'] = current_window
                client_data['requests'] = 0

    def request(self, client_id: str) -> int:
        if client_id not in self.clients:
            raise KeyError("Client not registered")
        client_data = self.clients[client_id]
        current_window = self.time // self.window
        if client_data['current_window'] != current_window:
            client_data['current_window'] = current_window
            client_data['requests'] = 0
        if client_data['requests'] >= client_data['allowance']:
            raise RateLimited("Rate limit exceeded")
        client_data['requests'] += 1
        self.receipt_counter += 1
        return self.receipt_counter

    def get_remaining(self, client_id: str) -> int:
        if client_id not in self.clients:
            raise KeyError("Client not registered")
        client_data = self.clients[client_id]
        current_window = self.time // self.window
        if client_data['current_window'] != current_window:
            client_data['current_window'] = current_window
            client_data['requests'] = 0
        return client_data['allowance'] - client_data['requests']

    def get_time(self) -> int:
        return self.time

    def get_clients(self) -> list[str]:
        return list(self.clients.keys())
